package com.nimbusbill.customer.controller; import com.nimbusbill.customer.dto.AiInsightResponse; import com.nimbusbill.customer.entity.AiRecommendation; import com.nimbusbill.customer.service.AiInsightService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/ai") public class AiInsightController{private final AiInsightService service;public AiInsightController(AiInsightService s){service=s;}@GetMapping("/insights") @PreAuthorize("hasAnyRole('ADMIN','BILLING_MANAGER','FINANCE','OPERATIONS','AUDITOR','AI_ANALYST')") public AiInsightResponse insights(@RequestParam(required=false) UUID customerId,Authentication a){return service.insights(customerId,a);}@PostMapping("/recommendations") @PreAuthorize("hasAnyRole('ADMIN','BILLING_MANAGER','AI_ANALYST')") public AiRecommendation generate(@RequestParam(required=false) UUID customerId,Authentication a){return service.generate(customerId,a);}@GetMapping("/recommendations") @PreAuthorize("hasAnyRole('ADMIN','BILLING_MANAGER','FINANCE','AUDITOR','AI_ANALYST')") public List<AiRecommendation> list(){return service.list();}@PostMapping("/recommendations/{id}/{decision}") @PreAuthorize("hasAnyRole('ADMIN','BILLING_MANAGER')") public AiRecommendation review(@PathVariable UUID id,@PathVariable String decision,@RequestBody(required=false) String comment,Authentication a){return service.review(id,decision.toUpperCase(),comment,a);}}
